import { Suspense } from 'react';
import { ProductList } from './products';
import { invalidateProductsCache } from './actions';

export default function Page() {
  return (
    <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Product Catalog with Cache Management</h1>

      <div style={{ marginBottom: '20px' }}>
        <form action={invalidateProductsCache}>
          <button
            type="submit"
            style={{
              padding: '10px 20px',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '14px'
            }}
          >
            Refresh Product Data
          </button>
        </form>
        <p style={{ fontSize: '12px', color: '#666', marginTop: '8px' }}>
          Click to invalidate the "products" cache and fetch fresh data
        </p>
      </div>

      <Suspense fallback={<div>Loading products...</div>}>
        <ProductList />
      </Suspense>
    </div>
  );
}

